// Night 5 — the offer. The woman in grey is being retired and offers her coat; Reyes offers Sunday; Sal gets asked for a number.
// Reads flags from nights 1–4. Sets: offer_grey, becoming_grey, reyes_deal, reyes_betrayed (only if knows_reyes), sal_exposed, leo_safe, dana_safe.
// Night-local flags (read only inside this night): grey_photo, marv_away, leo_eyes, leo_stays, used_the_name, walked_dana.
NIGHTS.push({
  id: 5,
  title: { en: 'Night five', ru: 'Ночь пятая', uk: 'Ніч п’ята', es: 'Quinta noche' },
  scenes: [
    {
      time: '23:00', name: { en: 'The drawer', ru: 'Ящик стола', uk: 'Шухляда', es: 'El cajón' }, voice: { gender: 'm', pitch: 0.75, rate: 0.92 },
      portrait: objectPortrait('#3a2a1a', '—'), start: 'a',
      nodes: {
        a: { who: 'narr', text: { en: "Night five. The rain is back, like it only left to think. Sal's note: 'Cop called in the day. Asked if you're the kind that leaves town. Said I don't know what kind you are.'", ru: 'Пятая ночь. Дождь вернулся, будто уходил только подумать. Записка от Сэла: «Днём звонила полицейская. Спросила, из тех ли ты, кто уезжает из города. Сказал, что не знаю, из каких ты».', uk: 'П’ята ніч. Дощ повернувся, наче відходив лише подумати. Записка від Села: «Удень дзвонила поліцейська. Спитала, чи ти з тих, хто виїжджає з міста. Сказав, що не знаю, з яких ти».', es: 'Quinta noche. La lluvia ha vuelto, como si solo se hubiera ido a pensar. Nota de Sal: «Llamó la policía, de día. Preguntó si eres {de los|de las} que se van de la ciudad. Le dije que no sé de qué clase eres».' },
             // This night's own flags start clean (nothing before night 5 can set them).
             effect: { flags: { offer_grey: false, becoming_grey: false, reyes_deal: false, reyes_betrayed: false, sal_exposed: false, leo_safe: false } },
             next: 'b' },
        b: { who: 'narr', text: (s) => s.flags.took_photos
              ? { en: "The drawer: the key, and the photographs from the wall upstairs, face down. You did not turn them over last night either. And something new, underneath.", ru: 'В ящике: ключ и фотографии со стены наверху, лицом вниз. Вчера вы их тоже не переворачивали. И под ними что-то новое.', uk: 'У шухляді: ключ і фотографії зі стіни нагорі, лицем донизу. Учора ви їх теж не перевертали. І під ними щось нове.', es: 'En el cajón: la llave y las fotografías de la pared de arriba, boca abajo. Anoche tampoco les dio la vuelta. Y debajo, algo nuevo.' }
              : s.flags.has_key
              ? { en: "The drawer: the key, brass tag, 12. It is warm. Keys shouldn't be. And something new, underneath.", ru: 'В ящике: ключ, латунная бирка, 12. Он тёплый. Ключи такими не бывают. И под ним что-то новое.', uk: 'У шухляді: ключ, латунна бирка, 12. Він теплий. Ключі такими не бувають. І під ним щось нове.', es: 'En el cajón: la llave, chapa de latón, 12. Está tibia. Las llaves no deberían estarlo. Y debajo, algo nuevo.' }
              : { en: "The drawer: room keys, a pen that doesn't write. And something new, underneath.", ru: 'В ящике: ключи от номеров, ручка, которая не пишет. И под ними что-то новое.', uk: 'У шухляді: ключі від номерів, ручка, яка не пише. І під ними щось нове.', es: 'En el cajón: llaves de habitaciones, un bolígrafo que no escribe. Y debajo, algo nuevo.' },
             next: 'c' },
        c: { who: 'narr', text: { en: "An envelope. No money with it. No name. On the front, very small, one word: her.", ru: 'Конверт. Без денег на этот раз. Без имени. На лицевой стороне, очень мелко, одно слово: ей.', uk: 'Конверт. Цього разу без грошей. Без імені. На лицьовому боці, дуже дрібно, одне слово: їй.', es: 'Un sobre. Esta vez sin dinero. Sin nombre. Delante, en letra muy pequeña, una palabra: ella.' },
             choices: [
               { text: { en: 'Open it.', ru: 'Открыть.', uk: 'Відкрити.', es: 'Abrirlo.' }, next: 'open', effect: { flags: { grey_photo: true } } },
               { text: { en: "Leave it sealed. It isn't yours.", ru: 'Не вскрывать. Он не ваш.', uk: 'Не розпечатувати. Він не ваш.', es: 'Dejarlo cerrado. No es suyo.' }, next: 'sealed' },
             ] },
        open: { who: 'narr', text: { en: "A photograph. Not you. The woman in grey, at a desk that isn't this one, an envelope in her hand. Taken from across the street. You know what a photograph means now.", ru: 'Фотография. Не вы. Женщина в сером, за стойкой, которая не эта, с конвертом в руке. Снято через дорогу. Вы теперь знаете, что значит фотография.', uk: 'Фотографія. Не ви. Жінка в сірому, за стійкою, яка не ця, з конвертом у руці. Знято через дорогу. Ви тепер знаєте, що означає фотографія.', es: 'Una fotografía. No es usted. La mujer de gris, en un mostrador que no es este, con un sobre en la mano. Tomada desde la acera de enfrente. Ahora ya sabe lo que significa una fotografía.' }, next: 'end' },
        sealed: { who: 'narr', text: { en: "You put it back. You are getting good at not opening things. That is also a skill, and they pay for it.", ru: 'Вы кладёте его обратно. У вас всё лучше получается не открывать. Это тоже навык, и за него платят.', uk: 'Ви кладете його назад. У вас дедалі краще виходить не відкривати. Це теж навичка, і за неї платять.', es: 'Lo vuelve a guardar. Cada vez se le da mejor no abrir cosas. También es un oficio, y se paga.' }, next: 'end' },
      }
    },
    {
      name: { en: 'Marv, room 7', ru: 'Марв, номер 7', uk: 'Марв, номер 7', es: 'Marv, habitación 7' }, voice: { gender: 'm', pitch: 0.85, rate: 0.9 },
      portrait: portrait('#4a5a6a', false, false), start: 'a',
      nodes: {
        a: { who: 'guest', effect: (s) => (s.flags.paid_marv ? { flags: { marv_thanked: true } } : {}), text: (s) => ((t) => (s.flags.paid_marv && !s.flags.marv_thanked ? { en: "Friday. Went to pay Sal this morning. Sal says the week's paid and it wasn't him. …Thank you. Don't say anything. …She's across the street. The grey one. Two hours. Not coming in.", ru: "Пятница. Пошёл утром платить Сэлу. Сэл говорит, неделя уже оплачена, а он тут ни при чём. …Спасибо. Ничего не говорите. …Она через дорогу. Та, в сером. Два часа. Не заходит.", uk: "П’ятниця. Пішов уранці платити Селу. Сел каже, тиждень уже оплачено, а він тут ні до чого. …Дякую. Нічого не кажіть. …Вона через дорогу. Та, в сірому. Дві години. Не заходить.", es: "Viernes. Esta mañana fui a pagarle a Sal. Dice que la semana ya está pagada y que él no tuvo nada que ver. …Gracias. No diga nada. …Está enfrente. La de gris. Dos horas. No entra." } : t))({ en: "Friday. Rent's Saturday. I've got it this time. Wanted you to know somebody in this building pays. …She's across the street. The grey one. Two hours. Not coming in.", ru: 'Пятница. Плата в субботу. На этот раз у меня есть. Хотел, чтобы вы знали: кто-то в этом доме платит. …Она через дорогу. Та, в сером. Два часа. Не заходит.', uk: 'П’ятниця. Платити в суботу. Цього разу в мене є. Хотів, щоб ви знали: хтось у цьому будинку платить. …Вона через дорогу. Та, в сірому. Дві години. Не заходить.', es: 'Viernes. El alquiler se paga el sábado. Esta vez lo tengo. Quería que supiera que en este edificio alguien paga. …Está enfrente. La de gris. Dos horas. No entra.' }), next: 'b' },
        b: { who: 'guest', text: { en: "I've seen that before. At bus stops. It's what a person looks like when the bus stopped running and nobody told them.", ru: 'Я такое видел. На остановках. Так выглядит человек, когда автобус отменили, а ему не сказали.', uk: 'Я таке бачив. На зупинках. Так виглядає людина, коли автобус скасували, а їй не сказали.', es: 'Eso ya lo he visto. En las paradas. Así se ve una persona cuando el autobús dejó de pasar y nadie se lo dijo.' },
             choices: (s) => [
               { text: { en: 'Give him sixty. "Sister\'s. Tomorrow night. Don\'t be here."', ru: 'Дать ему шестьдесят. «К сестре. Завтра вечером. Не будь здесь».', uk: 'Дати йому шістдесят. «До сестри. Завтра ввечері. Не будь тут».', es: 'Darle sesenta. «A casa de tu hermana. Mañana por la noche. No estés aquí».' }, next: 'sister', effect: { cash: -60, flags: { marv_away: true } } },
               s.flags.met_denis
                 ? { text: { en: '"Denis is alive, Marv. He\'s upstairs."', ru: '«Денис жив, Марв. Он наверху».', uk: '«Денис живий, Марве. Він нагорі».', es: '«Denis está vivo, Marv. Está arriba».' }, next: 'denis' }
                 : s.flags.marv_told
                 ? { text: { en: '"What did Denis say, the night he went up? Exactly."', ru: '«Что сказал Денис в ту ночь, когда ушёл наверх? Точно».', uk: '«Що сказав Денис тієї ночі, коли пішов нагору? Точно».', es: '«¿Qué dijo Denis la noche que subió? Exactamente».' }, next: 'said' }
                 : { text: { en: '"What does she want, Marv?"', ru: '«Чего она хочет, Марв?»', uk: '«Чого вона хоче, Марве?»', es: '«¿Qué quiere ella, Marv?»' }, next: 'want' },
               { text: { en: '"Go to bed, Marv."', ru: '«Иди спать, Марв».', uk: '«Іди спати, Марве».', es: '«Vete a dormir, Marv».' }, next: 'bed' },
             ] },
        sister: { who: 'guest', text: { en: "…Sixty. That's the fare and a sandwich. You worked that out. Twenty years, and it's the night clerk who works out the fare.", ru: '…Шестьдесят. Это билет и бутерброд. Вы посчитали. Двадцать лет, и билет мне считает ночной портье.', uk: '…Шістдесят. Це квиток і бутерброд. Ви порахували. Двадцять років, і квиток мені рахує нічний портьє.', es: '…Sesenta. El pasaje y un sándwich. Lo ha calculado. Veinte años, y quien me calcula el pasaje es {el|la} recepcionista de noche.' }, next: 'end' },
        denis: { who: 'guest', text: { en: "I know. I've heard him walk for a year. Thought if I never said it, it'd stop being true. …Does he still take his tea with nothing in it?", ru: 'Знаю. Я год слышу, как он ходит. Думал, если не говорить вслух, перестанет быть правдой. …Он всё ещё пьёт чай без ничего?', uk: 'Знаю. Я рік чую, як він ходить. Думав, якщо не казати вголос, перестане бути правдою. …Він досі п’є чай без нічого?', es: 'Lo sé. Hace un año que lo oigo caminar. Pensé que si nunca lo decía, dejaría de ser verdad. …¿Sigue tomando el té sin nada?' }, next: 'end' },
        said: { who: 'guest', text: { en: "'Room twelve.' Like he was giving me a room number. Like I'd need it. …I never have. That's the one thing I've done right in this building.", ru: '«Двенадцатый номер». Будто называл мне номер комнаты. Будто он мне понадобится. …Так и не понадобился. Единственное, что я сделал в этом доме правильно.', uk: '«Дванадцятий номер». Наче називав мені номер кімнати. Наче він мені знадобиться. …Так і не знадобився. Єдине, що я зробив у цьому будинку правильно.', es: '«La habitación doce». Como si me diera un número de habitación. Como si fuera a necesitarlo. …Nunca lo he necesitado. Es lo único que he hecho bien en este edificio.' }, next: 'end' },
        want: { who: 'guest', text: { en: "Same as anybody who stands in the rain outside a hotel. To be asked in. Nobody's going to ask her.", ru: 'Того же, что все, кто стоит под дождём у отеля. Чтобы позвали внутрь. Её никто не позовёт.', uk: 'Того ж, що й усі, хто стоїть під дощем біля готелю. Щоб покликали всередину. Її ніхто не покличе.', es: 'Lo mismo que cualquiera que se queda bajo la lluvia frente a un hotel. Que le digan que pase. Nadie se lo va a decir.' }, next: 'end' },
        bed: { who: 'guest', text: { en: "Right. Right. …Lock the door tonight. Not for her. For after.", ru: 'Ладно. Ладно. …Заприте сегодня дверь. Не от неё. От того, что после.', uk: 'Гаразд. Гаразд. …Замкніть сьогодні двері. Не від неї. Від того, що після.', es: 'Ya. Ya. …Cierre la puerta con llave esta noche. No por ella. Por lo que venga después.' }, next: 'end' },
      }
    },
    {
      name: { en: 'Leo', ru: 'Лео', uk: 'Лео', es: 'Leo' }, voice: { gender: 'm', pitch: 1.3, rate: 1.15 },
      portrait: portrait('#6a5a2a', true, false), start: 'a',
      when: (s) => s.flags.leo_friend || s.flags.leo_watch || s.flags.leo_followed || s.flags.kid_couch || (s.flags.kid_room && s.flags.lied_kid),
      nodes: {
        a: { who: 'guest', effect: (s) => (s.flags.leo_money ? { flags: { leo_thanked: true } } : {}), text: (s) => ((t) => (s.flags.leo_money && !s.flags.leo_thanked ? { en: "Somebody left fifty at the shelter. Envelope, my name on it. Nobody writes my name. …I carried it around an hour before I opened it. This hotel's rubbing off on me. " + t.en, ru: "Кто-то оставил в приюте пятьдесят. Конверт, на нём моё имя. Моё имя никто не пишет. …Я час носил его, прежде чем открыть. Ваш отель на меня плохо влияет. " + t.ru, uk: "Хтось залишив у притулку п’ятдесят. Конверт, на ньому моє ім’я. Моє ім’я ніхто не пише. …Я годину носив його, перш ніж відкрити. Ваш готель на мене погано впливає. " + t.uk, es: "Alguien dejó cincuenta en el albergue. Un sobre, con mi nombre. Nadie escribe mi nombre. …Lo llevé encima una hora antes de abrirlo. Este hotel se me está pegando. " + t.es } : t))(s.flags.leo_followed
              ? { en: "He goes up. I told you, and I watched again. The top-floor window that's never lit was lit. …Anyway. The shelter's got a bed with my name on it. Real name. On paper.", ru: 'Он идёт наверх. Я говорил вам и смотрел ещё раз. Окно на верхнем этаже, где никогда нет света, светилось. …Ладно. В приюте есть койка с моим именем. Настоящим. На бумаге.', uk: 'Він іде нагору. Я казав вам і дивився ще раз. Вікно на верхньому поверсі, де ніколи немає світла, світилося. …Гаразд. У притулку є ліжко з моїм іменем. Справжнім. На папері.', es: 'Sube. Se lo dije, y volví a mirar. La ventana del último piso, la que nunca tiene luz, estaba encendida. …En fin. En el albergue hay una cama con mi nombre. Mi nombre de verdad. En papel.' }
              : { en: "The shelter's got a bed with my name on it. Real name. On paper. They want an answer by tomorrow. …I told them I had a job here. I don't, do I.", ru: 'В приюте есть койка с моим именем. Настоящим. На бумаге. Ответ нужен до завтра. …Я сказал им, что у меня тут работа. Её же нет, да?', uk: 'У притулку є ліжко з моїм іменем. Справжнім. На папері. Відповідь потрібна до завтра. …Я сказав їм, що в мене тут робота. Її ж немає, так?', es: 'En el albergue hay una cama con mi nombre. Mi nombre de verdad. En papel. Quieren una respuesta para mañana. …Les dije que tenía trabajo aquí. No lo tengo, ¿verdad?' }),
             choices: [
               { text: { en: '"Take the bed. Don\'t come back here. That\'s not a punishment, Leo."', ru: '«Бери койку. Сюда не возвращайся. Это не наказание, Лео».', uk: '«Бери ліжко. Сюди не повертайся. Це не покарання, Лео».', es: '«Acepta la cama. No vuelvas aquí. No es un castigo, Leo».' }, next: 'bed', effect: { flags: { leo_safe: true } } },
               { text: { en: '"One more night. By the door at three. Then the bed."', ru: '«Ещё одна ночь. У двери в три. Потом койка».', uk: '«Ще одна ніч. Біля дверей о третій. Потім ліжко».', es: '«Una noche más. Junto a la puerta a las tres. Luego, la cama».' }, next: 'watch', effect: { flags: { leo_eyes: true } } },
               { text: { en: '"Couch, blanket. Stay as long as you like."', ru: '«Диван, плед. Оставайся, сколько хочешь».', uk: '«Диван, плед. Лишайся, скільки хочеш».', es: '«Sofá, manta. Quédate lo que quieras».' }, next: 'stay', effect: { flags: { leo_stays: true } } },
             ] },
        bed: { who: 'guest', text: { en: "…Okay. Okay. If a man in a good coat ever asks about me—", ru: '…Ладно. Ладно. Если мужчина в хорошем пальто когда-нибудь спросит обо мне…', uk: '…Гаразд. Гаразд. Якщо чоловік у гарному пальті колись спитає про мене…', es: '…Está bien. Está bien. Si alguna vez un hombre con un abrigo bueno pregunta por mí…' }, next: 'bed2' },
        bed2: { who: 'narr', text: { en: "'There's no Leo.' He almost smiles. He leaves the second coffee, the way he always does.", ru: '«Никакого Лео нет». Он почти улыбается. Оставляет второй кофе, как всегда.', uk: '«Ніякого Лео немає». Він майже всміхається. Лишає другу каву, як завжди.', es: '«No hay ningún Leo». Casi sonríe. Deja el segundo café, como siempre.' }, next: 'end' },
        watch: { who: 'guest', text: { en: "Three. By the door. …Watch for what this time?", ru: 'В три. У двери. …На что смотреть на этот раз?', uk: 'О третій. Біля дверей. …На що дивитися цього разу?', es: 'A las tres. Junto a la puerta. …¿Y qué vigilo esta vez?' }, next: 'watch2' },
        watch2: { who: 'narr', text: { en: "'A car. Anyone who sits in it and doesn't get out.' He doesn't ask whose. He has stopped asking whose.", ru: '«На машину. На любого, кто сидит в ней и не выходит». Он не спрашивает чью. Он перестал спрашивать чью.', uk: '«На машину. На будь-кого, хто сидить у ній і не виходить». Він не питає чию. Він перестав питати чию.', es: '«Un coche. Cualquiera que esté sentado dentro y no se baje». No pregunta de quién. Ha dejado de preguntar de quién.' }, next: 'end' },
        stay: { who: 'guest', text: { en: "Couch. …The first night was the good one. I didn't know it then.", ru: 'Диван. …Первая ночь была хорошая. Я тогда не знал.', uk: 'Диван. …Перша ніч була хороша. Я тоді не знав.', es: 'Sofá. …La primera noche fue la buena. Entonces no lo sabía.' }, next: 'end' },
      }
    },
    {
      time: '01:00', name: { en: "Leo's father", ru: 'Отец Лео', uk: 'Батько Лео', es: 'El padre de Leo' }, voice: { gender: 'm', pitch: 0.7, rate: 1.05 },
      portrait: portrait('#3a3a3a', false, false), start: 'a',
      when: (s) => s.flags.father_enemy || s.flags.father_card,
      nodes: {
        a: { who: 'narr', text: (s) => s.flags.leo_stays
              ? { en: "01:00. Leo's father. He doesn't shout this time. He puts both hands flat on the desk and looks past you, at the couch, at the shape under the blanket.", ru: '01:00. Отец Лео. На этот раз не кричит. Кладёт обе ладони на стойку и смотрит мимо вас, на диван, на очертания под пледом.', uk: '01:00. Батько Лео. Цього разу не кричить. Кладе обидві долоні на стійку і дивиться повз вас, на диван, на обриси під пледом.', es: '01:00. El padre de Leo. Esta vez no grita. Apoya las dos manos abiertas en el mostrador y mira más allá de usted, al sofá, al bulto bajo la manta.' }
              : { en: "01:00. Leo's father. He doesn't shout this time. He puts both hands flat on the desk, like a man who has been told to keep them where they can be seen.", ru: '01:00. Отец Лео. На этот раз не кричит. Кладёт обе ладони на стойку, как человек, которому велели держать руки на виду.', uk: '01:00. Батько Лео. Цього разу не кричить. Кладе обидві долоні на стійку, як людина, якій веліли тримати руки на видноті.', es: '01:00. El padre de Leo. Esta vez no grita. Apoya las dos manos abiertas en el mostrador, como alguien a quien le han dicho que las tenga a la vista.' },
             next: 'b' },
        b: { who: 'guest', text: (s) => s.flags.father_card
              ? { en: "The cop on your card called me. Once. Asked if my boy was home. …He's been seen here. Coffee cups. Coming and going. You said I scared him. I have thought about your face every day since.", ru: 'Полицейская с вашей визитки мне звонила. Один раз. Спросила, дома ли сын. …Его видели здесь. Стаканы из-под кофе. Приходит, уходит. Вы сказали, он меня боится. С тех пор я каждый день думаю о вашем лице.', uk: 'Поліцейська з вашої візитівки мені дзвонила. Один раз. Спитала, чи син удома. …Його бачили тут. Стаканчики з-під кави. Приходить, іде. Ви сказали, він мене боїться. Відтоді я щодня думаю про ваше обличчя.', es: 'Me llamó la agente de su tarjeta. Una vez. Preguntó si mi hijo estaba en casa. …Lo han visto aquí. Vasos de café. Entra y sale. Usted dijo que yo lo asustaba. Desde entonces pienso en su cara todos los días.' }
              : { en: "My boy's been seen here. Coffee cups. Coming and going. You said I scared him. I have thought about your face every day since.", ru: 'Моего сына видели здесь. Стаканы из-под кофе. Приходит, уходит. Вы сказали, он меня боится. С тех пор я каждый день думаю о вашем лице.', uk: 'Мого сина бачили тут. Стаканчики з-під кави. Приходить, іде. Ви сказали, він мене боїться. Відтоді я щодня думаю про ваше обличчя.', es: 'A mi hijo lo han visto aquí. Vasos de café. Entra y sale. Usted dijo que yo lo asustaba. Desde entonces pienso en su cara todos los días.' },
             choices: [
               { text: { en: '"He\'s safe. Somewhere with paperwork. That\'s all you get."', ru: '«Он в безопасности. Там, где есть бумаги. Это всё, что вы получите».', uk: '«Він у безпеці. Там, де є папери. Це все, що ви отримаєте».', es: '«Está a salvo. En un sitio con papeles. Es todo lo que le toca».' }, next: 'all', effect: { trouble: 1 } },
               { text: { en: '"Sit down. Tell me what you\'d say to him if he walked in."', ru: '«Сядьте. Скажите, что бы вы сказали ему, если бы он вошёл».', uk: '«Сядьте. Скажіть, що б ви сказали йому, якби він увійшов».', es: '«Siéntese. Dígame qué le diría si entrara por esa puerta».' }, next: 'sit' },
               { text: { en: '"A man comes here at three. Good coat. Last week he asked about you. By name."', ru: '«Сюда в три приходит мужчина. Хорошее пальто. На той неделе он спрашивал о вас. По имени».', uk: '«Сюди о третій приходить чоловік. Гарне пальто. Минулого тижня він питав про вас. На ім’я».', es: '«Aquí viene un hombre a las tres. Buen abrigo. La semana pasada preguntó por usted. Por su nombre».' }, next: 'name', effect: { flags: { used_the_name: true } } },
             ] },
        all: { who: 'guest', text: { en: "That's not all I get. …But it's all I get tonight.", ru: 'Это не всё, что я получу. …Но на сегодня всё.', uk: 'Це не все, що я отримаю. …Але на сьогодні все.', es: 'No es todo lo que me toca. …Pero es todo lo que me toca esta noche.' }, next: 'all2' },
        all2: { who: 'narr', text: (s) => s.flags.leo_stays
              ? { en: "He looks at the couch one more time. The blanket does not move. It is very good at not moving. He leaves.", ru: 'Он ещё раз смотрит на диван. Плед не шевелится. Он очень хорошо умеет не шевелиться. Уходит.', uk: 'Він ще раз дивиться на диван. Плед не ворушиться. Він дуже добре вміє не ворушитися. Іде.', es: 'Mira el sofá una vez más. La manta no se mueve. Se le da muy bien no moverse. Se va.' }
              : { en: "He leaves. He doesn't slam the door. He has learned that from somewhere.", ru: 'Он уходит. Не хлопает дверью. Этому он где-то научился.', uk: 'Він іде. Не грюкає дверима. Цього він десь навчився.', es: 'Se va. No da un portazo. Eso lo ha aprendido en alguna parte.' },
             next: 'end' },
        sit: { who: 'guest', text: { en: "…I'd say his mother's not well. That's true. …I'd say the other thing after. I always say the other thing after.", ru: '…Сказал бы, что мать нездорова. Это правда. …А другое сказал бы потом. Я всегда говорю другое потом.', uk: '…Сказав би, що мати нездужає. Це правда. …А інше сказав би потім. Я завжди кажу інше потім.', es: '…Le diría que su madre no está bien. Es verdad. …Lo otro se lo diría después. Lo otro siempre lo digo después.' }, next: 'sit2' },
        sit2: { who: 'narr', text: (s) => s.flags.leo_stays
              ? { en: "He sits for eleven minutes. Then he goes. Under the blanket, something stops pretending to be asleep.", ru: 'Он сидит одиннадцать минут. Потом уходит. Под пледом кто-то перестаёт притворяться спящим.', uk: 'Він сидить одинадцять хвилин. Потім іде. Під пледом хтось перестає вдавати, що спить.', es: 'Se queda sentado once minutos. Luego se va. Bajo la manta, algo deja de fingir que duerme.' }
              : { en: "He sits for eleven minutes. Then he goes. You do not tell him where the shelter is. He does not ask.", ru: 'Он сидит одиннадцать минут. Потом уходит. Вы не говорите ему, где приют. Он не спрашивает.', uk: 'Він сидить одинадцять хвилин. Потім іде. Ви не кажете йому, де притулок. Він не питає.', es: 'Se queda sentado once minutos. Luego se va. Usted no le dice dónde está el albergue. Él no pregunta.' },
             next: 'end' },
        name: { who: 'narr', text: (s) => s.flags.father_card
              ? { en: "He does not go white. 'A man in a coat. The cop on your card asked me about him too. Same words as yours.' He looks at you the way you look at a register that doesn't add up. He leaves without waiting for the answer.", ru: 'Он не белеет. «Мужчина в пальто. Полицейская с вашей визитки тоже о нём спрашивала. Теми же словами, что и вы». Он смотрит на вас так, как вы смотрите на кассу, которая не сходится. Уходит, не дожидаясь ответа.', uk: 'Він не біліє. «Чоловік у пальті. Поліцейська з вашої візитівки теж про нього питала. Тими самими словами, що й ви». Він дивиться на вас так, як ви дивитеся на касу, яка не сходиться. Іде, не чекаючи відповіді.', es: 'No palidece. «Un hombre con abrigo. La agente de su tarjeta también me preguntó por él. Con las mismas palabras que usted». {Lo|La} mira como usted mira una caja que no cuadra. Se va sin esperar respuesta.' }
              : { en: "You have never heard the man ask about anyone. It doesn't matter. He goes white the way people do when a rumour turns out to have their name in it. He leaves without a word.", ru: 'Вы ни разу не слышали, чтобы тот мужчина о ком-то спрашивал. Неважно. Он белеет так, как белеют люди, когда в слухе оказывается их имя. Уходит молча.', uk: 'Ви жодного разу не чули, щоб той чоловік про когось питав. Байдуже. Він біліє так, як біліють люди, коли в чутці виявляється їхнє ім’я. Іде мовчки.', es: 'Nunca ha oído a ese hombre preguntar por nadie. Da igual. Él palidece como palidece la gente cuando un rumor resulta llevar su nombre. Se va sin decir palabra.' },
              next: 'name2' },
        name2: { who: 'narr', text: (s) => s.flags.father_card
              ? { en: "You cannot tell whether it worked. He knows the name on the card is real; he has stopped needing you to tell him what else is.", ru: 'Вы не можете понять, сработало ли. Он знает, что имя на визитке настоящее; ему больше не нужно, чтобы вы говорили, что ещё настоящее.', uk: 'Ви не можете зрозуміти, чи спрацювало. Він знає, що ім’я на візитівці справжнє; йому більше не треба, щоб ви казали, що ще справжнє.', es: 'No sabe si ha funcionado. Él sabe que el nombre de la tarjeta es real; ya no necesita que usted le diga qué más lo es.' }
              : { en: "It worked. You notice that it worked. You notice that you noticed.", ru: 'Сработало. Вы замечаете, что сработало. Вы замечаете, что заметили.', uk: 'Спрацювало. Ви помічаєте, що спрацювало. Ви помічаєте, що помітили.', es: 'Ha funcionado. Se da cuenta de que ha funcionado. Se da cuenta de que se ha dado cuenta.' },
              next: 'end' },
      }
    },
    {
      time: '02:00', name: { en: 'Dana', ru: 'Дана', uk: 'Дана', es: 'Dana' }, voice: { gender: 'f', pitch: 1.05, rate: 1.0 },
      portrait: portrait('#8a3a5a', false, false), start: 'a',
      when: (s) => s.flags.dana_stays,
      nodes: {
        a: { who: 'narr', text: { en: "02:00. Dana, with the suitcase. Coat already on. She does not sit.", ru: '02:00. Дана, с чемоданом. Пальто уже надето. Она не садится.', uk: '02:00. Дана, з валізою. Пальто вже вдягнене. Вона не сідає.', es: '02:00. Dana, con la maleta. Ya lleva el abrigo puesto. No se sienta.' }, next: 'b' },
        b: { who: 'guest', effect: (s) => (s.flags.dana_money ? { flags: { dana_thanked: true } } : {}), text: (s) => ((t) => (s.flags.dana_money && !s.flags.dana_thanked ? (s.flags.rick_found ? { en: "There were eighty dollars under my door. No note. I'm not going to ask. …Thank you. " + t.en, ru: "Под дверью лежали восемьдесят долларов. Без записки. Я не буду спрашивать. …Спасибо. " + t.ru, uk: "Під дверима лежало вісімдесят доларів. Без записки. Я не питатиму. …Дякую. " + t.uk, es: "Había ochenta dólares bajo mi puerta. Sin nota. No voy a preguntar. …Gracias. " + t.es } : { en: "Five nights. I said a week. Off by two; that's not bad, for me. There's a bus at 5:40. Somebody put eighty dollars under my door, no note, so I have ninety-one past the ticket. …Thank you. I'm not going to ask who.", ru: "Пять ночей. Я говорила — неделя. Ошиблась на две; для меня это неплохо. В 5:40 автобус. Кто-то подсунул мне под дверь восемьдесят долларов, без записки, так что сверх билета у меня девяносто один. …Спасибо. Не буду спрашивать кто.", uk: "П’ять ночей. Я казала — тиждень. Помилилася на дві; для мене це непогано. О 5:40 автобус. Хтось підсунув мені під двері вісімдесят доларів, без записки, тож понад квиток у мене дев’яносто один. …Дякую. Не питатиму хто.", es: "Cinco noches. Dije una semana. Me equivoqué por dos; para mí no está mal. Hay un autobús a las 5:40. Alguien me pasó ochenta dólares por debajo de la puerta, sin nota, así que me sobran noventa y uno después del pasaje. …Gracias. No voy a preguntar quién." }) : t))(s.flags.rick_found
              ? { en: "He found the room. He didn't come in. He stood in the corridor and said my name like a question. I'm done being a question. There's a bus at 5:40.", ru: 'Он нашёл номер. Не вошёл. Стоял в коридоре и произнёс моё имя, как вопрос. Я больше не хочу быть вопросом. В 5:40 автобус.', uk: 'Він знайшов номер. Не увійшов. Стояв у коридорі й вимовив моє ім’я, як запитання. Я більше не хочу бути запитанням. О 5:40 автобус.', es: 'Encontró la habitación. No entró. Se quedó en el pasillo y dijo mi nombre como una pregunta. Ya no quiero ser una pregunta. Hay un autobús a las 5:40.' }
              : { en: "Five nights. I said a week. Off by two; that's not bad, for me. There's a bus at 5:40 and I have eleven dollars past the ticket.", ru: 'Пять ночей. Я говорила — неделя. Ошиблась на две; для меня это неплохо. В 5:40 автобус, и у меня одиннадцать долларов сверх билета.', uk: 'П’ять ночей. Я казала — тиждень. Помилилася на дві; для мене це непогано. О 5:40 автобус, і в мене одинадцять доларів понад квиток.', es: 'Cinco noches. Dije una semana. Me equivoqué por dos; para mí no está mal. Hay un autobús a las 5:40 y me sobran once dólares después del pasaje.' }),
             choices: [
               { text: { en: 'Take a hundred from the register. "Sal doesn\'t count it till morning."', ru: 'Взять сто из кассы. «Сэл считает только утром».', uk: 'Взяти сто з каси. «Сел рахує тільки вранці».', es: 'Sacar cien de la caja. «Sal no la cuenta hasta la mañana».' }, next: 'money', effect: { cash: -100, flags: { dana_safe: true } } },
               { text: { en: '"Wait till it\'s light. I\'ll walk you. Four blocks is a long way at four."', ru: '«Дождитесь света. Я вас провожу. Четыре квартала в четыре утра — это далеко».', uk: '«Дочекайтеся світла. Я вас проведу. Чотири квартали о четвертій ранку — це далеко».', es: '«Espere a que haya luz. La acompaño. Cuatro calles a las cuatro son mucho camino».' }, next: 'walk', effect: { flags: { dana_safe: true, walked_dana: true } } },
               { text: { en: '"Go now. Don\'t wait for anything, including me."', ru: '«Идите сейчас. Не ждите ничего, включая меня».', uk: '«Ідіть зараз. Не чекайте нічого, включно зі мною».', es: '«Váyase ya. No espere nada, ni siquiera a mí».' }, next: 'now', effect: { flags: { dana_safe: true } } },
             ] },
        money: { who: 'guest', text: { en: "That's Sal's. You'll be in trouble for it.", ru: 'Это Сэла. Вам достанется.', uk: 'Це Селове. Вам перепаде.', es: 'Eso es de Sal. Se va a meter en un lío.' }, next: 'money2' },
        money2: { who: 'narr', text: { en: "'I've got trouble already. This kind's mine.' She puts it in her coat, not the suitcase. Where people keep what they mean to use.", ru: '«Неприятности у меня и так есть. Эти хотя бы мои». Она кладёт деньги в пальто, не в чемодан. Туда, где держат то, чем собираются воспользоваться.', uk: '«Неприємності в мене й так є. Ці хоча б мої». Вона кладе гроші в пальто, не у валізу. Туди, де тримають те, чим збираються скористатися.', es: '«Líos ya tengo. Este, al menos, es mío». Lo guarda en el abrigo, no en la maleta. Donde se guarda lo que uno piensa usar.' }, next: 'end' },
        walk: { who: 'guest', text: { en: "…Nobody's walked me anywhere in six years. Okay. Light. I'll be by the door.", ru: '…Меня шесть лет никто никуда не провожал. Хорошо. Как рассветёт. Я буду у двери.', uk: '…Мене шість років ніхто нікуди не проводжав. Добре. Як розвидниться. Я буду біля дверей.', es: '…Hace seis años que nadie me acompaña a ningún sitio. Está bien. Con luz. Estaré junto a la puerta.' }, next: 'walk2' },
        walk2: { who: 'narr', text: { en: "At five you leave the desk. Four blocks in the rain, a suitcase between you. The bus is on time. Nobody has ever said that about this city.", ru: 'В пять вы оставляете стойку. Четыре квартала под дождём, чемодан между вами. Автобус приходит вовремя. Такого об этом городе ещё никто не говорил.', uk: 'О п’ятій ви залишаєте стійку. Чотири квартали під дощем, валіза між вами. Автобус приходить вчасно. Такого про це місто ще ніхто не казав.', es: 'A las cinco deja el mostrador. Cuatro calles bajo la lluvia, una maleta entre {los|las} dos. El autobús llega puntual. Nadie había dicho eso nunca de esta ciudad.' }, next: 'end' },
        now: { who: 'guest', text: { en: "Now. …You're the second person who ever told me that. The first one was me.", ru: 'Сейчас. …Вы второй человек, кто мне это сказал. Первой была я.', uk: 'Зараз. …Ви друга людина, яка мені це сказала. Першою була я.', es: 'Ahora. …Es usted la segunda persona que me lo dice. La primera fui yo.' }, next: 'now2' },
        now2: { who: 'narr', text: { en: "She goes. The door closes on her back this time, not her face. It is a better view.", ru: 'Она уходит. На этот раз дверь закрывается за её спиной, а не перед лицом. Так смотрится лучше.', uk: 'Вона йде. Цього разу двері зачиняються за її спиною, а не перед обличчям. Так виглядає краще.', es: 'Se va. Esta vez la puerta se cierra a su espalda, no en su cara. La vista es mejor.' }, next: 'end' },
      }
    },
    {
      time: '02:30', name: { en: 'The desk phone', ru: 'Телефон на стойке', uk: 'Телефон на стійці', es: 'El teléfono del mostrador' }, voice: { gender: 'm', pitch: 0.6, rate: 0.9 },
      portrait: objectPortrait('#2a2a2a', '☎'), start: 'a',
      nodes: {
        a: { who: 'narr', text: { en: "The desk phone. Not at three. Half past two. Whoever it is could not wait for three.", ru: 'Телефон на стойке. Не в три. В половине третьего. Кто бы это ни был, до трёх он не дотерпел.', uk: 'Телефон на стійці. Не о третій. О пів на третю. Хто б це не був, до третьої він не дотерпів.', es: 'El teléfono del mostrador. No a las tres. A las dos y media. Quienquiera que sea, no ha podido esperar a las tres.' }, next: 'b' },
        b: { who: 'guest', text: (s) => s.flags.met_denis
              ? { en: "It's Friday. She's coming tonight. Not him. Her. …Whatever she offers, ask what happened to the one before her.", ru: 'Сегодня пятница. Она придёт сегодня. Не он. Она. …Что бы она ни предложила, спросите, что стало с той, что была до неё.', uk: 'Сьогодні п’ятниця. Вона прийде сьогодні. Не він. Вона. …Хай що вона запропонує, спитайте, що сталося з тією, що була до неї.', es: 'Es viernes. Ella viene esta noche. No él. Ella. …Le ofrezca lo que le ofrezca, pregúntele qué fue de la que estaba antes que ella.' }
              : { en: "Clerk. Tonight someone comes instead of me. Listen to her. She has earned that. Then decide. I don't need an answer. I need a clerk.", ru: 'Портье. Сегодня вместо меня придёт другой человек. Выслушайте её. Она это заслужила. Потом решайте. Мне не нужен ответ. Мне нужен портье.', uk: 'Портьє. Сьогодні замість мене прийде інша людина. Вислухайте її. Вона це заслужила. Потім вирішуйте. Мені не потрібна відповідь. Мені потрібен портьє.', es: 'Recepcionista. Esta noche vendrá alguien en mi lugar. Escúchela. Se lo ha ganado. Luego decida. No necesito una respuesta. Necesito {un|una} recepcionista.' },
             choices: (s) => s.flags.met_denis
              ? [
                  { text: { en: '"What happened to the one before her?"', ru: '«Что стало с той, что была до неё?»', uk: '«Що сталося з тією, що була до неї?»', es: '«¿Qué fue de la que estaba antes que ella?»' }, next: 'before' },
                  { text: { en: '"Denis. Come down."', ru: '«Денис. Спускайтесь».', uk: '«Денисе. Спускайтеся».', es: '«Denis. Baje».' }, next: 'down' },
                  { text: { en: 'Hang up.', ru: 'Положить трубку.', uk: 'Покласти слухавку.', es: 'Colgar.' }, next: 'hang_d' },
                ]
              : [
                  { text: { en: '"Why her?"', ru: '«Почему она?»', uk: '«Чому вона?»', es: '«¿Por qué ella?»' }, next: 'why' },
                  { text: { en: '"And if I say no?"', ru: '«А если я откажусь?»', uk: '«А якщо я відмовлюся?»', es: '«¿Y si digo que no?»' }, next: 'ifno' },
                  { text: { en: '"Tell her not to bother." Hang up.', ru: '«Скажите ей, пусть не утруждается». Положить трубку.', uk: '«Скажіть їй, хай не завдає собі клопоту». Покласти слухавку.', es: '«Dígale que no se moleste». Colgar.' }, next: 'hang_m', effect: { trouble: 1 } },
                ] },
        before: { who: 'guest', text: { en: "She's upstairs. In a manner of speaking. Third photograph from the left. …He doesn't retire people, clerk. He files them.", ru: 'Она наверху. В некотором смысле. Третья фотография слева. …Он не отправляет людей на покой, портье. Он их подшивает к делу.', uk: 'Вона нагорі. У певному сенсі. Третя фотографія зліва. …Він не відправляє людей на спочинок, портьє. Він їх підшиває до справи.', es: 'Está arriba. Por así decirlo. Tercera fotografía por la izquierda. …Él no jubila a la gente, recepcionista. La archiva.' }, next: 'end' },
        down: { who: 'guest', text: { en: "Not tonight. …Tell Marv I hear him too. Tell him the tea's fine.", ru: 'Не сегодня. …Скажите Марву, что я тоже его слышу. Скажите, чай в порядке.', uk: 'Не сьогодні. …Скажіть Марву, що я теж його чую. Скажіть, чай нормальний.', es: 'Esta noche no. …Dígale a Marv que yo también lo oigo. Dígale que el té está bien.' }, next: 'end' },
        hang_d: { who: 'narr', text: { en: "You put it down. Upstairs, very faintly, someone puts theirs down too.", ru: 'Вы кладёте трубку. Наверху, едва слышно, кто-то кладёт свою.', uk: 'Ви кладете слухавку. Нагорі, ледь чутно, хтось кладе свою.', es: 'Cuelga. Arriba, muy débilmente, alguien cuelga también.' }, next: 'end' },
        why: { who: 'guest', text: { en: "Because she is tired. Because someone took her photograph. That is the whole of the rules, clerk. You already know them.", ru: 'Потому что она устала. Потому что кто-то сделал её фотографию. Вот и все правила, портье. Вы их уже знаете.', uk: 'Бо вона втомилася. Бо хтось зробив її фотографію. Оце й усі правила, портьє. Ви їх уже знаєте.', es: 'Porque está cansada. Porque alguien le hizo una fotografía. Esas son todas las reglas, recepcionista. Ya las conoce.' }, next: 'end' },
        ifno: { who: 'guest', text: { en: "Then you're a night clerk in a small hotel. That's not a threat. That's most people.", ru: 'Тогда вы ночной портье в маленьком отеле. Это не угроза. Это большинство людей.', uk: 'Тоді ви нічний портьє в маленькому готелі. Це не погроза. Це більшість людей.', es: 'Entonces es {un|una} recepcionista de noche en un hotel pequeño. No es una amenaza. Es lo que es casi todo el mundo.' }, next: 'end' },
        hang_m: { who: 'narr', text: { en: "Click. It does not ring again. That is new, and you do not like it.", ru: 'Щелчок. Больше не звонит. Это ново, и вам это не нравится.', uk: 'Клацання. Більше не дзвонить. Це нове, і вам це не подобається.', es: 'Clic. No vuelve a sonar. Eso es nuevo, y no le gusta.' }, next: 'end' },
      }
    },
    {
      time: '03:00', name: { en: 'The woman in grey', ru: 'Женщина в сером', uk: 'Жінка в сірому', es: 'La mujer de gris' }, voice: { gender: 'f', pitch: 0.8, rate: 0.88 },
      portrait: portrait('#5a5a5a', false, true), start: 'a',
      nodes: {
        a: { who: 'narr', text: (s) => s.flags.leo_eyes
              ? { en: "03:00. Leo, by the door, looks at the street, then at you, then at the street again: the car is still there. The door opens. Not him. Her.", ru: '03:00. Лео у двери смотрит на улицу, потом на вас, потом снова на улицу: машина всё ещё там. Дверь открывается. Не он. Она.', uk: '03:00. Лео біля дверей дивиться на вулицю, потім на вас, потім знову на вулицю: машина досі там. Двері відчиняються. Не він. Вона.', es: '03:00. Leo, junto a la puerta, mira a la calle, luego a usted, luego otra vez a la calle: el coche sigue ahí. Se abre la puerta. No es él. Es ella.' }
              : { en: "03:00. The door. Not him. Her.", ru: '03:00. Дверь. Не он. Она.', uk: '03:00. Двері. Не він. Вона.', es: '03:00. La puerta. No es él. Es ella.' },
             next: 'a2' },
        a2: { who: 'narr', text: { en: "She shakes the rain off, for the first time. Then she takes off the coat and lays it on the desk, folded, the way you'd lay down a weapon.", ru: 'Она впервые стряхивает дождь. Потом снимает пальто и кладёт на стойку, сложенное, как кладут оружие.', uk: 'Вона вперше струшує дощ. Потім знімає пальто і кладе на стійку, складене, як кладуть зброю.', es: 'Por primera vez se sacude la lluvia. Luego se quita el abrigo y lo deja en el mostrador, doblado, como quien deja un arma.' }, next: 'b' },
        b: { who: 'guest', text: (s) => s.flags.grey_photo
              ? { en: "Twelve years I have walked into rooms like this one. Tonight somebody left an envelope for me. You opened it. The seal. So you've seen my face the way I saw yours. Fair.", ru: 'Двенадцать лет я входила в такие комнаты. Сегодня кто-то оставил конверт для меня. Вы его вскрыли. Печать. Значит, вы видели моё лицо так, как я видела ваше. Справедливо.', uk: 'Дванадцять років я заходила в такі кімнати. Сьогодні хтось лишив конверт для мене. Ви його розпечатали. Печатка. Отже, ви бачили моє обличчя так, як я бачила ваше. Справедливо.', es: 'Doce años entrando en vestíbulos como este. Esta noche alguien dejó un sobre para mí. Usted lo abrió. El sello. Así que ha visto mi cara como yo vi la suya. Es justo.' }
              : { en: "Twelve years I have walked into rooms like this one. Tonight somebody left an envelope for me. My photograph. I know what it means. I have made forty of them.", ru: 'Двенадцать лет я входила в такие комнаты. Сегодня кто-то оставил конверт для меня. Моя фотография. Я знаю, что это значит. Я сделала сорок таких.', uk: 'Дванадцять років я заходила в такі кімнати. Сьогодні хтось лишив конверт для мене. Моя фотографія. Я знаю, що це означає. Я зробила сорок таких.', es: 'Doce años entrando en vestíbulos como este. Esta noche alguien dejó un sobre para mí. Mi fotografía. Sé lo que significa. Yo he hecho cuarenta.' },
             choices: [
               { text: { en: 'Let her talk.', ru: 'Дать ей договорить.', uk: 'Дати їй договорити.', es: 'Dejarla hablar.' }, next: 'c' },
               { text: { en: '"There is no room twelve. And nobody\'s on the desk tonight. Go home."', ru: '«Двенадцатого номера нет. И за стойкой сегодня никого. Идите домой».', uk: '«Дванадцятого номера немає. І за стійкою сьогодні нікого. Ідіть додому».', es: '«No hay habitación doce. Y esta noche no hay nadie en el mostrador. Váyase a casa».' }, next: 'shut' },
             ] },
        c: { who: 'guest', effect: { flags: { offer_grey: true } },
             text: (s) => s.flags.used_the_name
              ? { en: "You used his name tonight. On a father. I watched it work from across the street. …That's the job. Not the envelopes. That.", ru: 'Сегодня вы использовали его имя. Против отца. Я смотрела через дорогу, как это сработало. …Это и есть работа. Не конверты. Это.', uk: 'Сьогодні ви скористалися його ім’ям. Проти батька. Я дивилася через дорогу, як це спрацювало. …Це і є робота. Не конверти. Це.', es: 'Esta noche usó su nombre. Con un padre. Vi desde enfrente cómo funcionaba. …Ese es el trabajo. No los sobres. Eso.' }
              : s.flags.refused_twice
              ? { en: "You said no to me. Twice. That's why it's you. He has clerks who say yes; he has a building full of them. He needs one who can say no. To clerks.", ru: 'Вы сказали мне «нет». Дважды. Поэтому это вы. Портье, которые говорят «да», у него есть, целый дом. Ему нужен тот, кто умеет говорить «нет». Портье.', uk: 'Ви сказали мені «ні». Двічі. Тому це ви. Портьє, які кажуть «так», у нього є, цілий будинок. Йому потрібен той, хто вміє казати «ні». Портьє.', es: 'Me dijo que no. Dos veces. Por eso es usted. Recepcionistas que dicen que sí le sobran; tiene un edificio lleno. Necesita a alguien que sepa decir que no. A los recepcionistas.' }
              : (s.flags.delivered || s.flags.man_side || s.flags.took_late)
              ? { en: "He said you'd say yes. I said you'd ask what it costs first. One of us is about to lose a bet, and I'd rather it were him, just once.", ru: 'Он сказал, вы согласитесь. Я сказала, вы сначала спросите, чего это стоит. Кто-то из нас сейчас проиграет спор, и я бы хотела, чтобы это был он. Хоть раз.', uk: 'Він сказав, ви погодитеся. Я сказала, ви спершу спитаєте, чого це коштує. Хтось із нас зараз програє суперечку, і я б хотіла, щоб це був він. Хоч раз.', es: 'Él dijo que usted aceptaría. Yo dije que antes preguntaría cuánto cuesta. Uno de los dos está a punto de perder una apuesta, y preferiría que fuera él, por una vez.' }
              : { en: "You have an honest face. I told you the first night: those are expensive. I didn't tell you who buys them.", ru: 'У вас честное лицо. Я сказала это в первую ночь: такие дорого стоят. Я не сказала, кто их покупает.', uk: 'У вас чесне обличчя. Я сказала це першої ночі: такі дорого коштують. Я не сказала, хто їх купує.', es: 'Tiene una cara honrada. Se lo dije la primera noche: esas salen caras. No le dije quién las compra.' },
             next: 'c2' },
        c2: { who: 'guest', text: { en: "The coat is the job. Someone walks in the rain, leaves an envelope with an honest face, and says: there is no room twelve. You've said it. You said it well. It's yours, if you want it.", ru: 'Пальто — это и есть работа. Кто-то идёт под дождём, оставляет конверт честному лицу и говорит: двенадцатого номера нет. Вы это говорили. Говорили хорошо. Оно ваше, если хотите.', uk: 'Пальто — це і є робота. Хтось іде під дощем, лишає конверт чесному обличчю й каже: дванадцятого номера немає. Ви це казали. Казали добре. Воно ваше, якщо хочете.', es: 'El abrigo es el trabajo. Alguien camina bajo la lluvia, le deja un sobre a una cara honrada y dice: no hay habitación doce. Usted lo ha dicho. Lo dijo bien. Es suyo, si lo quiere.' },
              choices: [
                { text: { en: 'Take the coat.', ru: 'Взять пальто.', uk: 'Взяти пальто.', es: 'Tomar el abrigo.' }, next: 'yes', effect: { flags: { becoming_grey: true } } },
                { text: { en: '"What happens to you?"', ru: '«Что будет с вами?»', uk: '«Що буде з вами?»', es: '«¿Y qué será de usted?»' }, next: 'her' },
                { text: { en: '"No."', ru: '«Нет».', uk: '«Ні».', es: '«No».' }, next: 'no' },
              ] },
        her: { who: 'guest', text: (s) => s.flags.met_denis
              ? { en: "Room twelve has a bed. Denis keeps it made. You've seen it. …No. That's what I tell clerks. What happens is: I stop. There's a photograph, and then there's a woman who used to own a coat.", ru: 'В двенадцатом номере есть кровать. Денис её застилает. Вы видели. …Нет. Это я говорю портье. А будет вот что: я останавливаюсь. Есть фотография, а потом есть женщина, у которой когда-то было пальто.', uk: 'У дванадцятому номері є ліжко. Денис його застеляє. Ви бачили. …Ні. Це я кажу портьє. А буде ось що: я зупиняюся. Є фотографія, а потім є жінка, у якої колись було пальто.', es: 'En la habitación doce hay una cama. Denis la tiene hecha. Usted la ha visto. …No. Eso es lo que les cuento a los recepcionistas. Lo que pasa es esto: me detengo. Hay una fotografía, y luego hay una mujer que antes tenía un abrigo.' }
              : { en: "Room twelve has a bed. Denis keeps it made. …No. That's what I tell clerks. What happens is: I stop. There's a photograph, and then there's a woman who used to own a coat.", ru: 'В двенадцатом номере есть кровать. Денис её застилает. …Нет. Это я говорю портье. А будет вот что: я останавливаюсь. Есть фотография, а потом есть женщина, у которой когда-то было пальто.', uk: 'У дванадцятому номері є ліжко. Денис його застеляє. …Ні. Це я кажу портьє. А буде ось що: я зупиняюся. Є фотографія, а потім є жінка, у якої колись було пальто.', es: 'En la habitación doce hay una cama. Denis la tiene hecha. …No. Eso es lo que les cuento a los recepcionistas. Lo que pasa es esto: me detengo. Hay una fotografía, y luego hay una mujer que antes tenía un abrigo.' },
             choices: [
               { text: { en: 'Take the coat.', ru: 'Взять пальто.', uk: 'Взяти пальто.', es: 'Tomar el abrigo.' }, next: 'yes', effect: { flags: { becoming_grey: true } } },
               { text: { en: '"No."', ru: '«Нет».', uk: '«Ні».', es: '«No».' }, next: 'no' },
             ] },
        yes: { who: 'guest', text: { en: "It's warm. Don't wear it tomorrow. Wear it the night after, somewhere else. The envelopes come to you now. You'll know the desks. You have one of those faces; so did I.", ru: 'Оно тёплое. Завтра не надевайте. Наденьте послезавтра, в другом месте. Конверты теперь приходят к вам. Вы узнаете стойки. У вас такое лицо; у меня было такое же.', uk: 'Воно тепле. Завтра не вдягайте. Вдягніть післязавтра, деінде. Конверти тепер приходять до вас. Ви впізнаватимете стійки. У вас таке обличчя; у мене було таке саме.', es: 'Está caliente. No se lo ponga mañana. Póngaselo pasado mañana, en otro sitio. Ahora los sobres le llegan a usted. Reconocerá los mostradores. Tiene una de esas caras; yo también la tenía.' }, next: 'yes2' },
        yes2: { who: 'narr', text: { en: "It fits. That is the worst part. Across the street she stands in the rain for a while, without a coat, and then she does not.", ru: 'Оно впору. Это хуже всего. Через дорогу она какое-то время стоит под дождём без пальто, а потом не стоит.', uk: 'Воно якраз. Це найгірше. Через дорогу вона якийсь час стоїть під дощем без пальта, а потім не стоїть.', es: 'Le queda bien. Eso es lo peor. Enfrente, ella se queda un rato bajo la lluvia, sin abrigo, y luego ya no.' }, next: 'end' },
        no: { who: 'guest', text: { en: "Then he'll ask somebody else. He always has somebody else. …I'd still lock the door tonight. Not for him. For me; I'll be out there a while.", ru: 'Тогда он спросит кого-то другого. У него всегда есть кто-то другой. …Я бы всё же заперла сегодня дверь. Не от него. От меня; я ещё побуду там.', uk: 'Тоді він спитає когось іншого. У нього завжди є хтось інший. …Я б усе ж замкнула сьогодні двері. Не від нього. Від мене; я ще побуду там.', es: 'Entonces se lo pedirá a otro. Siempre tiene a otro. …Yo, de todos modos, cerraría la puerta con llave esta noche. No por él. Por mí; voy a estar ahí fuera un rato.' }, next: 'no2' },
        no2: { who: 'narr', text: { en: "She puts the coat back on. It looks heavier going on than it did coming off.", ru: 'Она снова надевает пальто. Надевается оно тяжелее, чем снималось.', uk: 'Вона знову вдягає пальто. Вдягається воно важче, ніж знімалося.', es: 'Vuelve a ponerse el abrigo. Parece pesar más al ponérselo que al quitárselo.' }, next: 'end' },
        shut: { who: 'guest', text: { en: "…That's the sentence. You said it to me. Properly, with the door behind it. He was right about you. I'll tell him I never came in.", ru: '…Это та самая фраза. Вы сказали её мне. Как следует, с дверью за спиной. Он был прав насчёт вас. Я скажу ему, что не заходила.', uk: '…Це та сама фраза. Ви сказали її мені. Як слід, із дверима за спиною. Він мав рацію щодо вас. Я скажу йому, що не заходила.', es: '…Esa es la frase. Me la ha dicho a mí. Como se debe, con la puerta detrás. Él tenía razón sobre usted. Le diré que nunca entré.' }, next: 'shut2' },
        shut2: { who: 'narr', text: { en: "She takes the coat and goes. That was the offer. You did not hear it, which is one way of answering.", ru: 'Она берёт пальто и уходит. Это и было предложение. Вы его не выслушали, и это тоже ответ.', uk: 'Вона бере пальто і йде. Це і була пропозиція. Ви її не вислухали, і це теж відповідь.', es: 'Toma el abrigo y se va. Esa era la oferta. Usted no la escuchó, que es una forma de responder.' }, next: 'end' },
      }
    },
    {
      time: '05:40', name: { en: 'Officer Reyes', ru: 'Офицер Рейес', uk: 'Офіцер Реєс', es: 'Agente Reyes' }, voice: { gender: 'f', pitch: 0.95, rate: 1.0 },
      portrait: portrait('#2a3a6a', true, false), start: 'a',
      nodes: {
        a: { who: 'narr', text: (s) => s.flags.walked_dana
              ? { en: "05:50. You come back from the bus with rain in your shoes. Reyes is sitting behind the desk. Your desk. She has made coffee.", ru: '05:50. Вы возвращаетесь с автобуса, в ботинках дождь. Рейес сидит за стойкой. Вашей стойкой. Она сварила кофе.', uk: '05:50. Ви повертаєтеся з автобуса, в черевиках дощ. Реєс сидить за стійкою. Вашою стійкою. Вона зварила каву.', es: '05:50. Vuelve del autobús con lluvia en los zapatos. Reyes está sentada tras el mostrador. En su sitio, el de usted. Ha hecho café.' }
              : s.flags.becoming_grey
              ? { en: "05:40. Reyes. She looks at the coat on the back of your chair for a long moment. She doesn't ask. Asking is a thing she has stopped doing.", ru: '05:40. Рейес. Она долго смотрит на пальто на спинке вашего стула. Не спрашивает. Спрашивать она перестала.', uk: '05:40. Реєс. Вона довго дивиться на пальто на спинці вашого стільця. Не питає. Питати вона перестала.', es: '05:40. Reyes. Mira largo rato el abrigo en el respaldo de su silla. No pregunta. Preguntar es algo que ha dejado de hacer.' }
              : { en: "05:40. Reyes. Wet. She doesn't look at the drawer this time. She looks at you like a form she has already filled in.", ru: '05:40. Рейес. Мокрая. На ящик на этот раз не смотрит. Смотрит на вас, как на бланк, который уже заполнила.', uk: '05:40. Реєс. Мокра. На шухляду цього разу не дивиться. Дивиться на вас, як на бланк, який уже заповнила.', es: '05:40. Reyes. Mojada. Esta vez no mira el cajón. {Lo|La} mira a usted como a un formulario que ya ha completado.' },
             next: 'b' },
        b: { who: 'guest', text: (s) => s.flags.took_photos
              ? { en: "You have the photographs. I have a prosecutor who owes me and a programme with a house in a city where it doesn't rain. Testimony, and you're gone by Sunday. New name. That's the whole offer.", ru: 'У вас фотографии. У меня прокурор, который мне должен, и программа с домом в городе, где не идёт дождь. Показания — и к воскресенью вас здесь нет. Новое имя. Вот и всё предложение.', uk: 'У вас фотографії. У мене прокурор, який мені винен, і програма з будинком у місті, де не йде дощ. Свідчення — і до неділі вас тут немає. Нове ім’я. Ось і вся пропозиція.', es: 'Usted tiene las fotografías. Yo tengo un fiscal que me debe un favor y un programa con una casa en una ciudad donde no llueve. Testifique, y el domingo ya no estará aquí. Nombre nuevo. Esa es toda la oferta.' }
              : s.flags.denis_ally
              ? { en: "Denis will talk; he told me so through a door. I need someone who was downstairs. Statement, everything. Immunity, relocation. Sunday you're a person in a city with no room twelve.", ru: 'Денис будет говорить; он сказал мне это через дверь. Мне нужен кто-то, кто был внизу. Показания, всё. Иммунитет, переезд. В воскресенье вы человек в городе, где нет двенадцатого номера.', uk: 'Денис говоритиме; він сказав мені це через двері. Мені потрібен хтось, хто був унизу. Свідчення, все. Імунітет, переїзд. У неділю ви людина в місті, де немає дванадцятого номера.', es: 'Denis hablará; me lo dijo a través de una puerta. Necesito a alguien que estuviera abajo. Declaración, todo. Inmunidad, traslado. El domingo es usted una persona en una ciudad sin habitación doce.' }
              : s.flags.reyes_side
              ? { en: "You picked a side. Now I make it paper. Immunity. Relocation. Sunday you're a person in a city with no room twelve. Say yes and I can sleep.", ru: 'Вы выбрали сторону. Теперь я оформлю это на бумаге. Иммунитет. Переезд. В воскресенье вы человек в городе, где нет двенадцатого номера. Скажите «да», и я смогу спать.', uk: 'Ви обрали сторону. Тепер я оформлю це на папері. Імунітет. Переїзд. У неділю ви людина в місті, де немає дванадцятого номера. Скажіть «так», і я зможу спати.', es: 'Eligió un bando. Ahora lo paso a papel. Inmunidad. Traslado. El domingo es usted una persona en una ciudad sin habitación doce. Diga que sí y podré dormir.' }
              : s.flags.man_side
              ? { en: "You picked him. Fine. This is the one door out, and I'm holding it open exactly as long as it takes to say yes. Immunity. Relocation. Sunday.", ru: 'Вы выбрали его. Ладно. Это единственный выход, и я держу дверь открытой ровно столько, сколько нужно, чтобы сказать «да». Иммунитет. Переезд. Воскресенье.', uk: 'Ви обрали його. Гаразд. Це єдиний вихід, і я тримаю двері відчиненими рівно стільки, скільки треба, щоб сказати «так». Імунітет. Переїзд. Неділя.', es: 'Lo eligió a él. Bien. Esta es la única salida, y le sostengo la puerta exactamente lo que se tarda en decir que sí. Inmunidad. Traslado. Domingo.' }
              : { en: "Two clerks before you, I was already on him. I'm tired, clerk. Give me a statement: the envelopes, the phone, her. Immunity. Relocation. Sunday you're gone and it never rained on you.", ru: 'Я работала над ним ещё за двух портье до вас. Я устала, портье. Дайте показания: конверты, телефон, она. Иммунитет. Переезд. В воскресенье вас нет, и дождь на вас никогда не шёл.', uk: 'Я працювала над ним ще за двох портьє до вас. Я втомилася, портьє. Дайте свідчення: конверти, телефон, вона. Імунітет. Переїзд. У неділю вас немає, і дощ на вас ніколи не йшов.', es: 'Dos recepcionistas antes que usted, yo ya iba tras él. Estoy cansada, recepcionista. Deme una declaración: los sobres, el teléfono, ella. Inmunidad. Traslado. El domingo se habrá ido y nunca le habrá llovido encima.' },
             choices: [
               { text: { en: '"Yes. Sunday."', ru: '«Да. Воскресенье».', uk: '«Так. Неділя».', es: '«Sí. El domingo».' }, next: 'deal', effect: { flags: { reyes_deal: true } } },
               { text: { en: '"What does he get?"', ru: '«А что получит он?»', uk: '«А що отримає він?»', es: '«¿Y él qué se lleva?»' }, next: (s) => (s.flags.knows_reyes ? 'probe_k' : 'probe') },
               { text: { en: '"No."', ru: '«Нет».', uk: '«Ні».', es: '«No».' }, next: 'refuse' },
             ] },
        deal: { who: 'guest', text: (s) => s.flags.knows_reyes
              ? { en: "Good. …He'll want to see the statement before it's filed. That's— procedure. Write it tonight. All of it.", ru: 'Хорошо. …Он захочет увидеть показания до того, как их подошьют. Это… процедура. Напишите сегодня. Всё.', uk: 'Добре. …Він захоче побачити свідчення до того, як їх підшиють. Це… процедура. Напишіть сьогодні. Все.', es: 'Bien. …Él querrá ver la declaración antes de que se archive. Es… el procedimiento. Escríbala esta noche. Toda.' }
              : { en: "Good. Write it tonight. All of it. I'll be back at six with a car and a person who knows how to lose a name.", ru: 'Хорошо. Напишите сегодня. Всё. Я вернусь в шесть с машиной и человеком, который умеет терять имена.', uk: 'Добре. Напишіть сьогодні. Все. Я повернуся о шостій із машиною і людиною, яка вміє губити імена.', es: 'Bien. Escríbala esta noche. Toda. Vuelvo a las seis con un coche y con alguien que sabe hacer desaparecer un nombre.' },
             choices: (s) => s.flags.knows_reyes
              ? [
                  { text: { en: '"\'He\'? …You\'re going to show it to him."', ru: '«Он»? …Вы покажете это ему».', uk: '«Він»? …Ви покажете це йому».', es: '«¿Él? …Va a enseñársela a él».' }, next: 'burn', effect: { flags: { reyes_betrayed: true } } },
                  { text: { en: '"Procedure. Fine. Sunday."', ru: '«Процедура. Ладно. Воскресенье».', uk: '«Процедура. Гаразд. Неділя».', es: '«El procedimiento. Bien. El domingo».' }, next: 'fine' },
                ]
              : null,
             next: 'deal2' },
        deal2: { who: 'narr', text: { en: "She leaves. At the door she says 'Sunday' again, to herself, like a word she is checking still works.", ru: 'Она уходит. У двери снова говорит «воскресенье», себе, как слово, которое проверяет — работает ли ещё.', uk: 'Вона йде. Біля дверей знову каже «неділя», собі, як слово, яке перевіряє — чи ще працює.', es: 'Se va. En la puerta vuelve a decir «domingo», para sí, como una palabra que comprueba si aún funciona.' }, next: 'end' },
        burn: { who: 'guest', text: { en: "…Yes. I am. And then he decides which of us gets filed. It's been me for three years, clerk. I'm not offering you a way out. I'm asking you to hold the door.", ru: '…Да. Покажу. А потом он решит, кого из нас подшить к делу. Три года это была я, портье. Я не предлагаю вам выход. Я прошу вас подержать дверь.', uk: '…Так. Покажу. А потім він вирішить, кого з нас підшити до справи. Три роки це була я, портьє. Я не пропоную вам вихід. Я прошу вас потримати двері.', es: '…Sí. Se la voy a enseñar. Y luego él decide a cuál de {los|las} dos archiva. Hace tres años que soy yo, recepcionista. No le ofrezco una salida. Le pido que me sostenga la puerta.' },
                choices: [
                  { text: { en: '"Then I\'m holding it. Sunday."', ru: '«Тогда держу. Воскресенье».', uk: '«Тоді тримаю. Неділя».', es: '«Entonces la sostengo. El domingo».' }, next: 'hold' },
                  { text: { en: '"Tear it up. I was never here."', ru: '«Порвите. Меня здесь не было».', uk: '«Порвіть. Мене тут не було».', es: '«Rómpala. Yo nunca estuve aquí».' }, next: 'tear', effect: { flags: { reyes_deal: false } } },
                ] },
        hold: { who: 'narr', text: { en: "She nods. It is the first time you have seen her look grateful, and it looks like grief.", ru: 'Она кивает. Вы впервые видите её благодарной, и это похоже на горе.', uk: 'Вона киває. Ви вперше бачите її вдячною, і це схоже на горе.', es: 'Asiente. Es la primera vez que la ve agradecida, y se parece al duelo.' }, next: 'end' },
        tear: { who: 'guest', text: { en: "…That's the sentence. Everybody in this building knows the sentence. Go home, clerk. Lock something.", ru: '…Та самая фраза. В этом доме все знают эту фразу. Идите домой, портье. Заприте что-нибудь.', uk: '…Та сама фраза. У цьому будинку всі знають цю фразу. Ідіть додому, портьє. Замкніть щось.', es: '…Esa es la frase. Todo el mundo en este edificio se sabe la frase. Váyase a casa, recepcionista. Cierre algo con llave.' }, next: 'end' },
        fine: { who: 'guest', text: { en: "Sunday. …You're better at not asking than Denis was. That's a compliment. It's the only kind I have left.", ru: 'Воскресенье. …Вы лучше Дениса умеете не спрашивать. Это комплимент. Других у меня не осталось.', uk: 'Неділя. …Ви краще за Дениса вмієте не питати. Це комплімент. Інших у мене не лишилося.', es: 'El domingo. …A usted se le da mejor que a Denis no preguntar. Es un cumplido. Es el único tipo que me queda.' }, next: 'end' },
        probe: { who: 'guest', text: { en: "A trial. Eventually. …You want honest? He gets a clerk who left town, and I get a statement in a drawer. That's what I've got. Yes or no.", ru: 'Суд. Когда-нибудь. …Хотите честно? Он получает портье, который уехал, а я — показания в ящике. Вот что у меня есть. Да или нет.', uk: 'Суд. Колись. …Хочете чесно? Він отримує портьє, який поїхав, а я — свідчення в шухляді. Ось що в мене є. Так чи ні.', es: 'Un juicio. Algún día. …¿Quiere sinceridad? Él se queda con {un|una} recepcionista que se fue de la ciudad, y yo con una declaración en un cajón. Eso es lo que tengo. ¿Sí o no?' },
                 choices: [
                   { text: { en: '"Yes."', ru: '«Да».', uk: '«Так».', es: '«Sí».' }, next: 'deal', effect: { flags: { reyes_deal: true } } },
                   { text: { en: '"No."', ru: '«Нет».', uk: '«Ні».', es: '«No».' }, next: 'refuse' },
                 ] },
        probe_k: { who: 'narr', text: (s) => s.flags.leo_eyes
              ? { en: "She stops. Leo, at the door, holds up two fingers and points across the street. A car. Someone in it, in a good coat, since midnight.", ru: 'Она замолкает. Лео у двери поднимает два пальца и показывает через дорогу. Машина. В ней кто-то в хорошем пальто, с полуночи.', uk: 'Вона замовкає. Лео біля дверей піднімає два пальці й показує через дорогу. Машина. У ній хтось у гарному пальті, з півночі.', es: 'Se calla. Leo, en la puerta, levanta dos dedos y señala la acera de enfrente. Un coche. Alguien dentro, con un abrigo bueno, desde medianoche.' }
              : { en: "She stops. She looks at the window. There is a car across the street. There has been since midnight. She knew that before you did.", ru: 'Она замолкает. Смотрит в окно. Через дорогу стоит машина. Стоит с полуночи. Она знала это раньше вас.', uk: 'Вона замовкає. Дивиться у вікно. Через дорогу стоїть машина. Стоїть з півночі. Вона знала це раніше за вас.', es: 'Se calla. Mira por la ventana. Hay un coche enfrente. Lleva ahí desde medianoche. Ella lo sabía antes que usted.' },
                   choices: [
                     { text: { en: '"You\'d burn me to keep him."', ru: '«Вы сожжёте меня, чтобы сохранить его».', uk: '«Ви спалите мене, щоб зберегти його».', es: '«Me quemaría a mí para quedarse con él».' }, next: 'seen', effect: { flags: { reyes_betrayed: true } } },
                     { text: { en: '"Sunday, then."', ru: '«Тогда воскресенье».', uk: '«Тоді неділя».', es: '«Entonces, el domingo».' }, next: 'deal', effect: { flags: { reyes_deal: true } } },
                   ] },
        seen: { who: 'guest', text: { en: "…I'd burn me first, if that worked. It doesn't. Yes or no, clerk. I'm asking as the last honest thing I'll do tonight.", ru: '…Я бы сначала сожгла себя, если бы это работало. Не работает. Да или нет, портье. Спрашиваю как последнее честное, что сделаю сегодня.', uk: '…Я б спершу спалила себе, якби це працювало. Не працює. Так чи ні, портьє. Питаю як останнє чесне, що зроблю сьогодні.', es: '…Me quemaría a mí primero, si eso sirviera. No sirve. ¿Sí o no, recepcionista? Se lo pregunto como lo último honrado que haré esta noche.' },
                choices: [
                  { text: { en: '"Yes. Burn me somewhere warm."', ru: '«Да. Сожгите меня где-нибудь, где тепло».', uk: '«Так. Спаліть мене десь, де тепло».', es: '«Sí. Quémeme en algún sitio cálido».' }, next: 'hold', effect: { flags: { reyes_deal: true } } },
                  { text: { en: '"No."', ru: '«Нет».', uk: '«Ні».', es: '«No».' }, next: 'refuse2' },
                ] },
        refuse: { who: 'guest', text: { en: "Denis said no too. Denis is in a room with no number. …The card's still good. It won't be next week.", ru: 'Денис тоже сказал «нет». Денис в номере без номера. …Визитка ещё действует. На той неделе уже не будет.', uk: 'Денис теж сказав «ні». Денис у номері без номера. …Візитівка ще дійсна. Наступного тижня вже не буде.', es: 'Denis también dijo que no. Denis está en una habitación sin número. …La tarjeta aún vale. La semana que viene ya no.' }, next: 'end' },
        refuse2: { who: 'guest', text: { en: "Smart. …Smart. I'd have said no too, once. The car outside will wait for whoever says yes next.", ru: 'Умно. …Умно. Когда-то я бы тоже отказалась. Машина у входа дождётся того, кто следующим скажет «да».', uk: 'Розумно. …Розумно. Колись я б теж відмовилася. Машина біля входу дочекається того, хто наступним скаже «так».', es: 'Inteligente. …Inteligente. Yo también habría dicho que no, en otra época. El coche de ahí fuera esperará a quien diga que sí después.' }, next: 'end' },
      }
    },
    {
      time: '06:00', name: { en: 'Sal (the manager)', ru: 'Сэл (управляющий)', uk: 'Сел (управитель)', es: 'Sal (el gerente)' }, voice: { gender: 'm', pitch: 0.7, rate: 1.05 },
      portrait: portrait('#7a2a2a', false, true), start: 'a',
      nodes: {
        a: { who: 'guest', text: (s) => s.flags.walked_dana
              ? { en: "Morning. I called at five. Nobody picked up. The desk was empty. …Where were you.", ru: 'Утро. Я звонил в пять. Никто не взял. Стойка пустая. …Где тебя носило.', uk: 'Ранок. Я дзвонив о п’ятій. Ніхто не взяв. Стійка порожня. …Де тебе носило.', es: 'Buenos días. Llamé a las cinco. No contestó nadie. El mostrador, vacío. …¿Dónde te habías metido?' }
              : s.flags.becoming_grey
              ? { en: "Morning. Register. …That's her coat. On my chair. Don't tell me. I've never asked; that's what the money's for.", ru: 'Утро. Касса. …Это её пальто. На моём стуле. Не рассказывай. Я никогда не спрашивал; за это и деньги.', uk: 'Ранок. Каса. …Це її пальто. На моєму стільці. Не розповідай. Я ніколи не питав; за це й гроші.', es: 'Buenos días. La caja. …Ese es el abrigo de ella. En mi silla. No me lo cuentes. Nunca he preguntado; para eso es el dinero.' }
              : s.flags.dana_deal
              ? { en: "Morning. Room 4 paid four and stayed seven. Whose idea was that. …Register.", ru: 'Утро. Четвёртый номер заплатил за четыре, а прожил семь. Чья это была идея. …Касса.', uk: 'Ранок. Четвертий номер заплатив за чотири, а прожив сім. Чия це була ідея. …Каса.', es: 'Buenos días. La 4 pagó cuatro noches y se quedó siete. ¿De quién fue la idea? …La caja.' }
              : s.flags.marv_away
              ? { en: "Morning. Marv paid and left a note. 'Sister's.' Twenty years and I get a note. …Register.", ru: 'Утро. Марв заплатил и оставил записку. «К сестре». Двадцать лет, и мне достаётся записка. …Касса.', uk: 'Ранок. Марв заплатив і лишив записку. «До сестри». Двадцять років, і мені дістається записка. …Каса.', es: 'Buenos días. Marv pagó y dejó una nota. «A casa de mi hermana». Veinte años y me toca una nota. …La caja.' }
              : s.flags.leo_stays
              ? { en: "Morning. Why is the kid on my couch again. …Never mind. Register.", ru: 'Утро. Почему парень опять на моём диване. …Неважно. Касса.', uk: 'Ранок. Чому хлопець знову на моєму дивані. …Байдуже. Каса.', es: 'Buenos días. ¿Por qué está otra vez el chico en mi sofá? …Da igual. La caja.' }
              : { en: "Morning. Register. It's Saturday, in case nobody told you. Rent day. Everybody's.", ru: 'Утро. Касса. Сегодня суббота, если тебе никто не сказал. День оплаты. У всех.', uk: 'Ранок. Каса. Сьогодні субота, якщо тобі ніхто не сказав. День оплати. У всіх.', es: 'Buenos días. La caja. Hoy es sábado, por si nadie te lo ha dicho. Día de pagar. Para todos.' },
             effect: (s) => (s.flags.walked_dana ? { trouble: 1 } : {}),
             choices: (s) => [
               s.flags.sal_cut
                 ? { text: { en: '"You told me yourself, Wednesday. Now I want a number, Sal. Per night."', ru: '«Вы сами сказали мне в среду. Теперь я хочу цифру, Сэл. За ночь».', uk: '«Ви самі сказали мені в середу. Тепер я хочу цифру, Селе. За ніч».', es: '«Me lo dijo usted mismo, el miércoles. Ahora quiero una cifra, Sal. Por noche».' }, next: 'number', effect: { trouble: 1, flags: { sal_exposed: true } } }
                 : { text: { en: '"How much is your cut, Sal. Per night. I want a number."', ru: '«Сколько ваша доля, Сэл. За ночь. Я хочу цифру».', uk: '«Скільки ваша частка, Селе. За ніч. Я хочу цифру».', es: '«¿Cuánto es su parte, Sal? Por noche. Quiero una cifra».' }, next: 'number', effect: { trouble: 1, flags: { sal_exposed: true } } },
               ...(s.flags.took_photos
                 ? [{ text: { en: 'Slide a photograph across the desk. His face is on that wall too.', ru: 'Подвинуть по стойке фотографию. Его лицо тоже на той стене.', uk: 'Посунути по стійці фотографію. Його обличчя теж на тій стіні.', es: 'Deslizar una fotografía por el mostrador. Su cara también está en esa pared.' }, next: 'photo', effect: { flags: { sal_exposed: true } } }]
                 : []),
               { text: { en: '"Register\'s fine, Sal."', ru: '«С кассой всё в порядке, Сэл».', uk: '«З касою все гаразд, Селе».', es: '«La caja está bien, Sal».' }, next: 'fine' },
             ] },
        number: { who: 'guest', text: { en: "…Two hundred, a night he comes. Fifty the rest. Two years. Don't do the maths, clerk. I did it once. It's why I don't sleep days.", ru: '…Двести — в ночь, когда он приходит. Пятьдесят — в остальные. Два года. Не считай, портье. Я посчитал один раз. Поэтому и не сплю днём.', uk: '…Двісті — у ніч, коли він приходить. П’ятдесят — у решту. Два роки. Не рахуй, портьє. Я порахував один раз. Тому й не сплю вдень.', es: '…Doscientos la noche que viene él. Cincuenta las demás. Dos años. No hagas la cuenta, recepcionista. Yo la hice una vez. Por eso no duermo de día.' }, next: 'number2' },
        number2: { who: 'narr', text: { en: "He counts the register. He does not look at you. He never has. That is what the cut is for.", ru: 'Он считает кассу. На вас не смотрит. Он никогда не смотрел. За это и доля.', uk: 'Він рахує касу. На вас не дивиться. Він ніколи не дивився. За це й частка.', es: 'Cuenta la caja. No {lo|la} mira. Nunca lo ha hecho. Para eso es su parte.' }, next: 'end' },
        photo: { who: 'guest', text: { en: "…That's 2011. I had hair. …He said the wall was for clerks. I said I'm not a clerk. He said: everybody's a clerk.", ru: '…Это 2011-й. У меня были волосы. …Он сказал, стена для портье. Я сказал, что я не портье. Он сказал: все — портье.', uk: '…Це 2011-й. У мене було волосся. …Він сказав, стіна для портьє. Я сказав, що я не портьє. Він сказав: усі — портьє.', es: '…Eso es de 2011. Tenía pelo. …Él dijo que la pared era para recepcionistas. Yo le dije que no soy recepcionista. Él dijo: todo el mundo es recepcionista.' }, next: 'photo2' },
        photo2: { who: 'narr', text: { en: "He puts the photograph in his pocket. Not the register. His pocket. Then he counts the money, slower than usual, like it's someone else's.", ru: 'Он кладёт фотографию в карман. Не в кассу. В карман. Потом считает деньги, медленнее обычного, будто они чужие.', uk: 'Він кладе фотографію в кишеню. Не в касу. У кишеню. Потім рахує гроші, повільніше, ніж зазвичай, наче вони чужі.', es: 'Se guarda la fotografía en el bolsillo. No en la caja. En el bolsillo. Luego cuenta el dinero, más despacio que de costumbre, como si fuera de otro.' }, next: 'end' },
        fine: { who: 'guest', text: (s) => s.flags.becoming_grey
              ? { en: "Fine. …It's a good coat. Don't wear it in here.", ru: 'Ладно. …Хорошее пальто. Здесь его не носи.', uk: 'Гаразд. …Гарне пальто. Тут його не носи.', es: 'Bien. …Es un buen abrigo. Aquí dentro no te lo pongas.' }
              : { en: "Fine. Fine is what I pay for.", ru: 'Ладно. За «ладно» я и плачу.', uk: 'Гаразд. За «гаразд» я і плачу.', es: 'Bien. «Bien» es lo que yo pago.' },
             next: 'end' },
      }
    },
  ],
  pickEnding(state) {
    const f = state.flags;
    if (state.trouble >= TROUBLE_MAX) return 'fired';
    if (f.becoming_grey && f.reyes_deal) return 'double';
    if (f.becoming_grey) return 'coat';
    if (f.reyes_deal && f.reyes_betrayed) return 'sunday';
    if (f.reyes_deal) return 'witness';
    if (f.sal_exposed) return 'number';
    if (!f.offer_grey) return 'sentence';
    return 'alone';
  },
  endings: {
    fired: {
      en: ['SHIFT OVER', "Sal reads the trouble off your face before you reach the register; he has been adding it up all week, and tonight closes the account. 'Don't come back.' Across the street, a woman watches you leave and offers you nothing."],
      ru: ['СМЕНА ОКОНЧЕНА', 'Сэл читает проблемы по вашему лицу раньше, чем вы дошли до кассы; он складывал их всю неделю, и сегодняшняя ночь закрывает счёт. «Не возвращайся». Через дорогу женщина смотрит, как вы уходите, и ничего вам не предлагает.'],
      uk: ['ЗМІНУ ЗАКІНЧЕНО', 'Сел читає проблеми з вашого обличчя раніше, ніж ви дійшли до каси; він складав їх увесь тиждень, і сьогоднішня ніч закриває рахунок. «Не повертайся». Через дорогу жінка дивиться, як ви йдете, і нічого вам не пропонує.'], es: ['FIN DEL TURNO', 'Sal le lee los problemas en la cara antes de que llegue a la caja; lleva toda la semana sumándolos, y esta noche cierra la cuenta. «No vuelvas». En la acera de enfrente, una mujer {lo|la} ve marcharse y no le ofrece nada.'] },
    coat: {
      en: ['THE COAT', "It fits. Tomorrow you are a night clerk. The night after, somewhere else, you are the one who leaves the envelope. You already know which desks."],
      ru: ['ПАЛЬТО', 'Оно впору. Завтра вы ночной портье. Послезавтра, в другом месте, конверт на стойку кладёте вы. Вы уже знаете, какие стойки.'],
      uk: ['ПАЛЬТО', 'Воно якраз. Завтра ви нічний портьє. Післязавтра, деінде, конверт на стійку кладете ви. Ви вже знаєте, які стійки.'], es: ['EL ABRIGO', 'Le queda bien. Mañana es {un|una} recepcionista de noche. Pasado mañana, en otro sitio, es usted quien deja el sobre. Ya sabe en qué mostradores.'] },
    double: {
      en: ['TWO PROMISES', "Her coat on your chair. Reyes's Sunday in your pocket. One of them is a lie, and you are no longer sure it is Reyes's."],
      ru: ['ДВА ОБЕЩАНИЯ', 'Её пальто на вашем стуле. Воскресенье Рейес у вас в кармане. Одно из них — ложь, и вы уже не уверены, что это воскресенье.'],
      uk: ['ДВІ ОБІЦЯНКИ', 'Її пальто на вашому стільці. Неділя Реєс у вашій кишені. Одне з них — брехня, і ви вже не певні, що це неділя.'], es: ['DOS PROMESAS', 'El abrigo de ella en su silla. El domingo de Reyes en su bolsillo. Una de las dos es mentira, y ya no {está seguro|está segura} de que sea la de Reyes.'] },
    sunday: {
      en: ['SUNDAY', "You said yes knowing what yes is. She will show him the statement, and he will decide which of you gets filed. You are holding a door for a woman who is holding it for him."],
      ru: ['ВОСКРЕСЕНЬЕ', 'Вы сказали «да», зная, что такое «да». Она покажет ему показания, и он решит, кого из вас подшить к делу. Вы держите дверь женщине, которая держит её ему.'],
      uk: ['НЕДІЛЯ', 'Ви сказали «так», знаючи, що таке «так». Вона покаже йому свідчення, і він вирішить, кого з вас підшити до справи. Ви тримаєте двері жінці, яка тримає їх йому.'], es: ['DOMINGO', 'Dijo que sí sabiendo lo que es un sí. Ella le enseñará la declaración, y él decidirá a cuál de {los|las} dos archiva. Usted le sostiene la puerta a una mujer que se la sostiene a él.'] },
    witness: {
      en: ['WITNESS', "Immunity. Relocation. Sunday. You write it all down tonight: the envelopes, the phone, her. It takes four pages. You leave the last line blank."],
      ru: ['СВИДЕТЕЛЬ', 'Иммунитет. Переезд. Воскресенье. Вы записываете всё сегодня: конверты, телефон, её. Выходит четыре страницы. Последнюю строчку вы оставляете пустой.'],
      uk: ['СВІДОК', 'Імунітет. Переїзд. Неділя. Ви записуєте все сьогодні: конверти, телефон, її. Виходить чотири сторінки. Останній рядок ви лишаєте порожнім.'], es: ['TESTIGO', 'Inmunidad. Traslado. Domingo. Esta noche lo escribe todo: los sobres, el teléfono, ella. Son cuatro páginas. Deja en blanco la última línea.'] },
    number: {
      en: ['THE NUMBER', "Sal counts the register with his back to you. He has never turned his back on the desk before. Now two people in this building know what the cut buys, and neither of them sleeps days."],
      ru: ['ЦИФРА', 'Сэл считает кассу спиной к вам. Раньше он никогда не поворачивался к стойке спиной. Теперь в этом доме двое знают, что покупает доля, и оба не спят днём.'],
      uk: ['ЦИФРА', 'Сел рахує касу спиною до вас. Раніше він ніколи не повертався до стійки спиною. Тепер у цьому будинку двоє знають, що купує частка, і обидва не сплять удень.'], es: ['LA CIFRA', 'Sal cuenta la caja de espaldas a usted. Nunca antes le había dado la espalda al mostrador. Ahora dos personas en este edificio saben qué compra su parte, y ninguna de las dos duerme de día.'] },
    sentence: {
      en: ['THE SENTENCE', "There is no room twelve. You said it to her, and she took her coat and went. Somewhere in the rain she is telling him you never let her in, which is exactly what he wanted to hear."],
      ru: ['ТА САМАЯ ФРАЗА', 'Двенадцатого номера нет. Вы сказали это ей, и она взяла пальто и ушла. Где-то под дождём она говорит ему, что вы её не впустили, и это ровно то, что он хотел услышать.'],
      uk: ['ТА САМА ФРАЗА', 'Дванадцятого номера немає. Ви сказали це їй, і вона взяла пальто й пішла. Десь під дощем вона каже йому, що ви її не впустили, і це саме те, що він хотів почути.'], es: ['LA FRASE', 'No hay habitación doce. Se lo dijo a ella, y ella tomó su abrigo y se fue. En algún lugar bajo la lluvia le está contando a él que usted nunca la dejó entrar, que es exactamente lo que él quería oír.'] },
    alone: {
      en: ['ALONE', "No coat. No Sunday. The register balances, and dawn comes up grey over a desk where you said no to everyone. It is very quiet."],
      ru: ['В ОДИНОЧЕСТВЕ', 'Ни пальто. Ни воскресенья. Касса сходится, и рассвет серым поднимается над стойкой, за которой вы всем сказали «нет». Очень тихо.'],
      uk: ['НА САМОТІ', 'Ні пальта. Ні неділі. Каса сходиться, і світанок сірим підіймається над стійкою, за якою ви всім сказали «ні». Дуже тихо.'], es: ['{SOLO|SOLA}', 'Sin abrigo. Sin domingo. La caja cuadra, y el alba sale gris sobre un mostrador donde usted les dijo que no a todos. Hay mucho silencio.'] },
  },
});
